WITH loss_agg AS ( SELECT cc.cc_call_center_id AS call_center_id, sm.sm_type AS ship_mode_type, w.w_warehouse_id AS warehouse_id, SUM(cr.cr_net_loss) AS total_net_loss FROM catalog_returns cr JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY cc.cc_call_center_id, sm.sm_type, w.w_warehouse_id ) SELECT call_center_id, ship_mode_type, warehouse_id, total_net_loss, CASE WHEN total_net_loss < 1000 THEN 'Low' WHEN total_net_loss < 5000 THEN 'Medium' ELSE 'High' END AS loss_severity, RANK() OVER (ORDER BY total_net_loss DESC) AS loss_rank FROM loss_agg ORDER BY loss_rank LIMIT 10
